// Wide Contract: No preconditions, always safe. Good candidate for noexcept.
class Circle {
    double radius_;
public:
    double get_radius() const noexcept { return radius_; }
    bool is_valid() const noexcept { return radius_ >= 0; }
};

// Narrow Contract: Preconditions exist. Caller must ensure validity.
// `at` throws on failure, so it cannot be noexcept.
// `operator[]` has UB on failure, could be noexcept, but it's a risky design.
class IntArray {
    int data_[10];
public:
    int at(int index) {
        if (index < 0 || index >= 10) {
            throw std::out_of_range("Index out of range");
        }
        return data_[index];
    }
};
